/**
 * Pilot Drill Formulas (65%, 70%, 75% Thread Engagement):
 *
 * 1. Cut Tapping (Standard 60° thread profile, Machinery's Handbook):
 *    Constant = 1.299 (Double thread depth factor: 2 * (3/4) * H = 1.299038 * P)
 *    Factors:
 *      65%: 1.299 * 0.65 = 0.84435
 *      70%: 1.299 * 0.70 = 0.9093
 *      75%: 1.299 * 0.75 = 0.97425
 *    - Unified (Inch):
 *        pilot{pct}In = MajorDia (in) - (Factor / TPI)
 *        pilot{pct}Mm = pilot{pct}In * 25.4
 *    - Metric (ISO):
 *        pilot{pct}Mm = MajorDia (mm) - (Factor * Pitch (mm))
 *        pilot{pct}In = pilot{pct}Mm / 25.4
 *
 * 2. Form Tapping (Roll / Forming Taps):
 *    Constant = 0.0068 (Material displacement factor)
 *    Factors:
 *      65%: 0.0068 * 65 = 0.442
 *      70%: 0.0068 * 70 = 0.476
 *      75%: 0.0068 * 75 = 0.510
 *    - Unified (Inch):
 *        pilot{pct}FormIn = MajorDia (in) - (Factor / TPI)
 *        pilot{pct}FormMm = pilot{pct}FormIn * 25.4
 *    - Metric (ISO):
 *        pilot{pct}FormMm = MajorDia (mm) - (Factor * Pitch (mm))
 *        pilot{pct}FormIn = pilot{pct}FormMm / 25.4
 */
